const KNOWN_TYPES = [
  "array",
  "boolean",
  "integer",
  "null",
  "number",
  "object",
  "string",
];

export function isType(instance, typeName) {
  switch (typeName) {
    case "null":
      return instance === null;
    case "boolean":
      return typeof instance === "boolean";
    case "object":
      return instance !== null && typeof instance === "object" && !Array.isArray(instance);
    case "array":
      return Array.isArray(instance);
    case "number":
      return typeof instance === "number";
    case "integer":
      return typeof instance === "number" && Number.isInteger(instance);
    case "string":
      return typeof instance === "string";
    default:
      return false;
  }
}

export function type(typeValue, instance, schema, ctx) {
  const types = Array.isArray(typeValue) ? typeValue : [typeValue];
  for (const typeName of types) {
    if (!KNOWN_TYPES.includes(typeName)) {
      throw new Error(`Unknown type: ${typeName}`);
    }
  }
  for (const typeName of types) {
    if (isType(instance, typeName)) {
      return [];
    }
  }
  return [{ keyword: "type" }];
}

