// Applicator keyword validators for Draft 7.
// Signature: (keywordValue, instance, schema, ctx) -> Array of error objects.
// These keywords apply to ALL instance types — no type guard.

export function allOf(v, instance, schema, ctx) {
  const errors = [];
  for (const subschema of v) {
    errors.push(...ctx.descend(instance, subschema));
  }
  return errors;
}

export function anyOf(v, instance, schema, ctx) {
  for (const subschema of v) {
    if (ctx.descend(instance, subschema).length === 0) return [];
  }
  return [{ keyword: "anyOf" }];
}

export function oneOf(v, instance, schema, ctx) {
  let validCount = 0;
  for (const subschema of v) {
    if (ctx.descend(instance, subschema).length === 0) validCount += 1;
  }
  if (validCount === 1) return [];
  return [{ keyword: "oneOf" }];
}

export function not(v, instance, schema, ctx) {
  if (ctx.descend(instance, v).length === 0) {
    return [{ keyword: "not" }];
  }
  return [];
}

export function if_(v, instance, schema, ctx) {
  // Called by the core only when "if" exists in schema.
  if (ctx.descend(instance, v).length === 0) {
    if ("then" in schema) {
      return ctx.descend(instance, schema.then);
    }
  } else {
    if ("else" in schema) {
      return ctx.descend(instance, schema.else);
    }
  }
  return [];
}

