// Numeric keyword validators for Draft 7 (parity with Python jsonschema 4.23.0).
// Each validator is (v, instance, schema, ctx) -> Array of error objects.
// All return [] unless instance is a number (checked BEFORE inspecting v).

function coerceBound(v) {
  if (typeof v === "boolean") return Number(v); // Python bools are ints
  if (typeof v !== "number") {
    // Python raises TypeError comparing int/float with non-number -> exit 1
    throw new TypeError(
      `Invalid value for numeric keyword: ${JSON.stringify(v)}`,
    );
  }
  return v;
}

export function minimum(v, instance, schema, ctx) {
  if (typeof instance !== "number") return [];
  const bound = coerceBound(v);
  if (instance < bound) {
    return [{ keyword: "minimum" }];
  }
  return [];
}

export function maximum(v, instance, schema, ctx) {
  if (typeof instance !== "number") return [];
  const bound = coerceBound(v);
  if (instance > bound) {
    return [{ keyword: "maximum" }];
  }
  return [];
}

export function exclusiveMinimum(v, instance, schema, ctx) {
  if (typeof instance !== "number") return [];
  const bound = coerceBound(v);
  if (instance <= bound) {
    return [{ keyword: "exclusiveMinimum" }];
  }
  return [];
}

export function exclusiveMaximum(v, instance, schema, ctx) {
  if (typeof instance !== "number") return [];
  const bound = coerceBound(v);
  if (instance >= bound) {
    return [{ keyword: "exclusiveMaximum" }];
  }
  return [];
}

export function multipleOf(v, instance, schema, ctx) {
  if (typeof instance !== "number") return [];
  if (typeof v === "boolean") v = Number(v);
  if (typeof v !== "number") {
    throw new TypeError(
      `Invalid value for numeric keyword: ${JSON.stringify(v)}`,
    );
  }
  if (v === 0) {
    // Python raises ZeroDivisionError -> exit 1
    throw new Error("division by zero (multipleOf: 0)");
  }

  let failed;
  if (Number.isInteger(v)) {
    failed = instance % v !== 0;
  } else {
    const q = instance / v;
    if (!Number.isFinite(q)) {
      // Python OverflowError fallback to the modulo operator
      failed = instance % v !== 0;
    } else {
      failed = Math.trunc(q) !== q;
    }
  }
  if (failed) {
    return [{ keyword: "multipleOf" }];
  }
  return [];
}

