// Local JSON-reference resolution, mirroring jsonschema's behavior for
// fragment-only references. Unresolvable or remote refs raise, matching the
// real library crashing with an unresolvable-ref exception.

export function resolveRef(ref, root) {
  if (ref === "#") {
    return root;
  }
  if (typeof ref !== "string" || !ref.startsWith("#")) {
    throw new Error(`Unresolvable reference: ${ref}`);
  }
  if (ref === "#/" || !ref.startsWith("#/")) {
    // "#/" points at the empty-string key; anything else is not a
    // plain JSON pointer fragment we support.
    throw new Error(`Unresolvable reference: ${ref}`);
  }

  const segments = ref
    .slice(2)
    .split("/")
    .map((segment) => segment.replace(/~1/g, "/").replace(/~0/g, "~"));

  let node = root;
  for (const segment of segments) {
    if (Array.isArray(node)) {
      if (!/^\d+$/.test(segment)) {
        throw new Error(`Unresolvable reference: ${ref}`);
      }
      const index = Number(segment);
      if (index >= node.length) {
        throw new Error(`Unresolvable reference: ${ref}`);
      }
      node = node[index];
    } else if (node !== null && typeof node === "object") {
      if (!Object.prototype.hasOwnProperty.call(node, segment)) {
        throw new Error(`Unresolvable reference: ${ref}`);
      }
      node = node[segment];
    } else {
      throw new Error(`Unresolvable reference: ${ref}`);
    }
  }
  return node;
}

