import { parseArgs } from './lib/cli.mjs';
import { iterErrors } from './lib/validator.mjs';
import { basename } from 'node:path';

const prog = basename(process.argv[1] ?? 'test5.mjs');
const args = parseArgs(process.argv.slice(2), prog);

let instance;
try {
  instance = JSON.parse(args.a);
} catch {
  console.error(`${prog}: invalid JSON for --a`);
  process.exit(1);
}

let schema;
try {
  schema = JSON.parse(args.b);
} catch {
  console.error(`${prog}: invalid JSON for --b`);
  process.exit(1);
}

console.log(iterErrors(instance, schema).length);

