// Core validation engine: evaluates an instance against a Draft-7 schema
// and returns the full array of error objects (only the length matters).

import { type } from './types.mjs';
import { enum_, const_ } from './basic.mjs';
import { minimum, maximum, exclusiveMinimum, exclusiveMaximum, multipleOf } from './numeric.mjs';
import { minLength, maxLength, pattern } from './strings.mjs';
import { items, additionalItems, contains, minItems, maxItems, uniqueItems } from './arrays.mjs';
import {
  properties,
  required,
  patternProperties,
  additionalProperties,
  dependencies,
  propertyNames,
  minProperties,
  maxProperties,
} from './objects.mjs';
import { allOf, anyOf, oneOf, not, if_ } from './applicators.mjs';
import { resolveRef } from './refs.mjs';

const VALIDATORS = {
  type,
  enum: enum_,
  const: const_,
  minimum,
  maximum,
  exclusiveMinimum,
  exclusiveMaximum,
  multipleOf,
  minLength,
  maxLength,
  pattern,
  items,
  additionalItems,
  contains,
  minItems,
  maxItems,
  uniqueItems,
  properties,
  required,
  patternProperties,
  additionalProperties,
  dependencies,
  propertyNames,
  minProperties,
  maxProperties,
  allOf,
  anyOf,
  oneOf,
  not,
  if: if_,
};

function evaluate(instance, schema, root) {
  if (schema === true) {
    return [];
  }
  if (schema === false) {
    return [{ keyword: 'false' }];
  }
  if (typeof schema !== 'object' || schema === null || Array.isArray(schema)) {
    return [];
  }

  // Draft-7 $ref: validate only against the resolved schema, ignore siblings.
  const ref = schema['$ref'];
  if (typeof ref === 'string') {
    return evaluate(instance, resolveRef(ref, root), root);
  }

  const ctx = {
    root,
    descend(subInstance, subschema) {
      return evaluate(subInstance, subschema, root);
    },
  };

  const errors = [];
  for (const key of Object.keys(schema)) {
    const validator = VALIDATORS[key];
    if (validator !== undefined) {
      const result = validator(schema[key], instance, schema, ctx);
      for (const error of result) {
        errors.push(error);
      }
    }
  }
  return errors;
}

export function iterErrors(instance, schema) {
  return evaluate(instance, schema, schema);
}

