// Object keyword validators for the Draft7Validator reimplementation.
// Every validator: (keywordValue, instance, schema, ctx) -> Array of error objects.
// All keywords here apply only to plain objects (non-null, typeof "object", not Array).

import { reSearch } from './strings.mjs';

function isObject(instance) {
  return typeof instance === 'object' && instance !== null && !Array.isArray(instance);
}

export function properties(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const errors = [];
  for (const key of Object.keys(v)) {
    if (Object.prototype.hasOwnProperty.call(instance, key)) {
      errors.push(...ctx.descend(instance[key], v[key]));
    }
  }
  return errors;
}

export function required(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const errors = [];
  for (const prop of v) {
    if (!Object.prototype.hasOwnProperty.call(instance, prop)) {
      errors.push({ keyword: 'required' });
    }
  }
  return errors;
}

export function patternProperties(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const errors = [];
  for (const [pattern, subschema] of Object.entries(v)) {
    for (const key of Object.keys(instance)) {
      if (reSearch(pattern, key)) {
        errors.push(...ctx.descend(instance[key], subschema));
      }
    }
  }
  return errors;
}

export function additionalProperties(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const declared = schema.properties ? Object.keys(schema.properties) : [];
  const patterns = schema.patternProperties ? Object.keys(schema.patternProperties) : [];
  const extras = [];
  for (const key of Object.keys(instance)) {
    if (declared.includes(key)) continue;
    if (patterns.some((pattern) => reSearch(pattern, key))) continue;
    extras.push(key);
  }
  if (v === false) {
    return extras.length > 0 ? [{ keyword: 'additionalProperties' }] : [];
  }
  if (v === true) {
    return [];
  }
  const errors = [];
  for (const key of extras) {
    errors.push(...ctx.descend(instance[key], v));
  }
  return errors;
}

export function propertyNames(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const errors = [];
  for (const key of Object.keys(instance)) {
    errors.push(...ctx.descend(key, v));
  }
  return errors;
}

export function dependencies(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  const errors = [];
  for (const [key, dep] of Object.entries(v)) {
    if (!Object.prototype.hasOwnProperty.call(instance, key)) continue;
    if (Array.isArray(dep)) {
      for (const needed of dep) {
        if (!Object.prototype.hasOwnProperty.call(instance, needed)) {
          errors.push({ keyword: 'dependencies' });
        }
      }
    } else {
      errors.push(...ctx.descend(instance, dep));
    }
  }
  return errors;
}

export function minProperties(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  return Object.keys(instance).length < v ? [{ keyword: 'minProperties' }] : [];
}

export function maxProperties(v, instance, schema, ctx) {
  if (!isObject(instance)) return [];
  return Object.keys(instance).length > v ? [{ keyword: 'maxProperties' }] : [];
}

