// jsonschema deep equality, mirroring Python jsonschema 4.23.0.
//
// Python semantics: jsonschema "unbools" values before comparing, so a
// boolean is NEVER equal to a number (true !== 1, false !== 0) even though
// Python's `==` says otherwise. Numbers compare by numeric value
// (1 == 1.0). null equals only null. Strings compare strictly. Arrays are
// ordered, element-wise equal. Objects are key-order-insensitive with equal
// key counts. Any other cross-type pair is unequal.
//
// Inputs come from JSON.parse, so only null / boolean / number / string /
// array / plain object can appear. No cycle guard needed.

export function equal(a, b) {
  // null equals only null
  if (a === null || b === null) {
    return a === b;
  }

  const typeA = Array.isArray(a) ? "array" : typeof a;
  const typeB = Array.isArray(b) ? "array" : typeof b;

  // Cross-type pairs (including boolean vs number) are never equal.
  if (typeA !== typeB) {
    return false;
  }

  switch (typeA) {
    case "boolean":
    case "string":
      return a === b;
    case "number":
      // Numeric comparison by value: 1 == 1.0, and NaN cannot appear
      // from JSON.parse.
      return a === b;
    case "array": {
      if (a.length !== b.length) {
        return false;
      }
      for (let i = 0; i < a.length; i++) {
        if (!equal(a[i], b[i])) {
          return false;
        }
      }
      return true;
    }
    case "object": {
      const keysA = Object.keys(a);
      const keysB = Object.keys(b);
      if (keysA.length !== keysB.length) {
        return false;
      }
      for (const key of keysA) {
        if (!Object.prototype.hasOwnProperty.call(b, key)) {
          return false;
        }
        if (!equal(a[key], b[key])) {
          return false;
        }
      }
      return true;
    }
    default:
      return false;
  }
}

