node -e '
import("/output/lib/numeric.mjs").then(m => {
  const cases = [
    [0.3, 0.1, true], [0.30000000000000004, 0.1, true], [300, 0.1, false],
    [6.02, 0.01, false], [0.15, 0.05, true], [5, 2.5, false], [6, 2.5, true],
    [3.3, 1.1, true], [0.0001, 0.00001, false], [19.99, 0.01, true],
    [-0.3, 0.1, true], [1e22, 3, true], [5, 3, true], [5, 2, false],
  ];
  let bad = 0;
  for (const [inst, v, expectErr] of cases) {
    const err = m.multipleOf(v, inst, {}, {}).length > 0;
    if (err !== expectErr) { bad++; console.log("MISMATCH", inst, v, "got", err, "want", expectErr); }
  }
  // guards and bounds
  const checks = [
    [m.minimum(5, "x", {}, {}).length === 0, "guard string"],
    [m.maximum(3, null, {}, {}).length === 0, "guard null"],
    [m.minimum(5, 4, {}, {}).length === 1, "minimum fail"],
    [m.minimum(5, 5, {}, {}).length === 0, "minimum equal ok"],
    [m.maximum(5, 6, {}, {}).length === 1, "maximum fail"],
    [m.exclusiveMinimum(5, 5, {}, {}).length === 1, "exclMin equal fail"],
    [m.exclusiveMinimum(true, 1, {}, {}).length === 1, "bool coerce v"],
    [m.exclusiveMaximum(5, 5, {}, {}).length === 1, "exclMax equal fail"],
  ];
  for (const [ok, name] of checks) if (!ok) { bad++; console.log("FAIL", name); }
  // throws
  for (const [fn, v, name] of [[m.multipleOf, 0, "multipleOf 0"], [m.minimum, "a", "minimum str"], [m.maximum, null, "maximum null"], [m.multipleOf, {}, "multipleOf obj"]]) {
    try { fn(v, 5, {}, {}); bad++; console.log("NO THROW", name); } catch {}
  }
  // v non-number but instance non-number: no throw
  try { m.minimum("a", "b", {}, {}); } catch { bad++; console.log("THROW on non-number instance"); }
  console.log(bad === 0 ? "ALL PASS" : bad + " FAILURES");
});
'

