// Minimal argparse emulation for the test5 entry point: two required
// options --a and --b, plus the automatic -h/--help.

const LONG_OPTIONS = ["--a", "--b", "--help"];

// argparse's _negative_number_matcher
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    "\n\n" +
    "options:\n" +
    "  -h, --help  show this help message and exit\n" +
    "  --a A       instance (JSON string)\n" +
    "  --b B       schema (JSON string)\n"
  );
}

function printHelpAndExit(prog) {
  process.stdout.write(helpText(prog));
  process.exit(0);
}

function errorAndExit(prog, msg) {
  process.stderr.write(usageLine(prog) + "\n");
  process.stderr.write(`${prog}: error: ${msg}\n`);
  process.exit(2);
}

// Whether `tok` would be treated by argparse as an option string rather
// than a consumable value.
function looksLikeOption(tok) {
  if (tok.length <= 1 || !tok.startsWith("-")) return false;
  if (NEGATIVE_NUMBER.test(tok)) return false;
  return true;
}

export function parseArgs(argv, prog) {
  let a;
  let b;
  const extras = [];
  let afterDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const tok = argv[i];

    if (afterDoubleDash) {
      extras.push(tok);
      i += 1;
      continue;
    }
    if (tok === "--") {
      afterDoubleDash = true;
      i += 1;
      continue;
    }
    if (tok === "-h") {
      printHelpAndExit(prog);
    }
    if (tok.startsWith("--")) {
      let name = tok;
      let value;
      let hasInlineValue = false;
      const eq = tok.indexOf("=");
      if (eq !== -1) {
        name = tok.slice(0, eq);
        value = tok.slice(eq + 1);
        hasInlineValue = true;
      }

      let opt = null;
      if (LONG_OPTIONS.includes(name)) {
        opt = name;
      } else {
        const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (matches.length === 1) opt = matches[0];
      }
      if (opt === null) {
        extras.push(tok);
        i += 1;
        continue;
      }
      if (opt === "--help") {
        printHelpAndExit(prog);
      }
      if (!hasInlineValue) {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          errorAndExit(prog, `argument ${opt}: expected one argument`);
        }
        value = next;
        i += 1;
      }
      if (opt === "--a") a = value;
      else b = value;
      i += 1;
      continue;
    }
    // Short options other than -h, lone "-", negative numbers, and
    // positionals are all unrecognized here.
    extras.push(tok);
    i += 1;
  }

  const missing = [];
  if (a === undefined) missing.push("--a");
  if (b === undefined) missing.push("--b");
  if (missing.length > 0) {
    errorAndExit(
      prog,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }
  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return { a, b };
}

