      let hasInlineValue = false;
      const eq = tok.indexOf("=");
      if (eq !== -1) {
        name = tok.slice(0, eq);
        value = tok.slice(eq + 1);
        hasInlineValue = true;
      }

      let opt = null;
      if (LONG_OPTIONS.includes(name)) {
        opt = name;
      } else {
        const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (matches.length === 1) opt = matches[0];
      }
      if (opt === null) {
        extras.push(tok);
        i += 1;
        continue;
      }
      if (opt === "--help") {
        printHelpAndExit(prog);
      }
      if (!hasInlineValue) {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          errorAndExit(prog, `argument ${opt}: expected one argument`);
        }
        value = next;
        i += 1;
      }
      if (opt === "--a") a = value;
      else b = value;
      i += 1;
      continue;
    }
    // Short options other than -h, lone "-", negative numbers, and
    // positionals are all unrecognized here.
    extras.push(tok);
    i += 1;
  }

  const missing = [];
  if (a === undefined) missing.push("--a");
  if (b === undefined) missing.push("--b");
  if (missing.length > 0) {
    errorAndExit(
      prog,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }
  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return { a, b };
}

