// String-related helpers for the Draft7Validator reimplementation.
// String length follows Python len(): Unicode code points, not UTF-16 units.

function codePointLength(str) {
  return Array.from(str).length;
}

// Strip unescaped whitespace and #-to-end-of-line comments (Python re.X /
// re.VERBOSE), keeping escapes and character-class contents intact.
function stripVerbose(pattern) {
  let out = "";
  let inClass = false;
  for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i];
    if (ch === "\\" && i + 1 < pattern.length) {
      out += ch + pattern[i + 1];
      i++;
      continue;
    }
    if (inClass) {
      if (ch === "]") inClass = false;
      out += ch;
      continue;
    }
    if (ch === "[") {
      inClass = true;
      out += ch;
      continue;
    }
    if (ch === "#") {
      while (i + 1 < pattern.length && pattern[i + 1] !== "\n") i++;
      continue;
    }
    if (/\s/.test(ch)) continue;
    out += ch;
  }
  return out;
}

// Python 3 re.search emulation: leading (?flags) inline-flag group with flags
// a nonempty subset of "imsx", plus Python's `$` matching just before ONE
// trailing newline (without re.M). RegExp construction errors are rethrown.
export function reSearch(pattern, str) {
  let flags = "";
  let source = pattern;
  let verbose = false;

  const m = /^\(\?([imsx]+)\)/.exec(source);
  if (m) {
    source = source.slice(m[0].length);
    for (const f of m[1]) {
      if (f === "x") verbose = true;
      else flags += f;
    }
  }
  if (verbose) source = stripVerbose(source);

  const re = new RegExp(source, flags);
  if (re.test(str)) return true;
  if (str.endsWith("\n")) return re.test(str.slice(0, -1));
  return false;
}

export function minLength(keywordValue, instance, schema, ctx) {
  if (typeof instance !== "string") return [];
  if (codePointLength(instance) < keywordValue) {
    return [{ keyword: "minLength" }];
  }
  return [];
}

export function maxLength(keywordValue, instance, schema, ctx) {
  if (typeof instance !== "string") return [];
  if (codePointLength(instance) > keywordValue) {
    return [{ keyword: "maxLength" }];
  }
  return [];
}

export function pattern(keywordValue, instance, schema, ctx) {
  if (typeof instance !== "string") return [];
  if (!reSearch(keywordValue, instance)) {
    return [{ keyword: "pattern" }];
  }
  return [];
}

