// Keyword validators for "enum" and "const" (Draft 7).
// Both apply to ALL instance types — no type guard.
// Error objects are opaque; only their count matters.

import { equal } from './equality.mjs';

// "enum": exactly one error iff NO element of v is equal to the instance.
// Python: if not any(equal(instance, each) for each in v): yield one error.
// Note: any() over an empty v is False, so an empty enum always yields
// exactly one error (matching Python's behavior).
export function enum_(v, instance, schema, ctx) {
  for (const each of v) {
    if (equal(each, instance)) {
      return [];
    }
  }
  return [{ keyword: 'enum' }];
}

// "const": exactly one error iff the instance is not equal to v.
export function const_(v, instance, schema, ctx) {
  if (equal(v, instance)) {
    return [];
  }
  return [{ keyword: 'const' }];
}

